import{_ as i,o as e,c as t,a2 as a}from"./chunks/framework.Desnpdez.js";const k=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"help/troubleshooting.md","filePath":"help/troubleshooting.md"}'),n={name:"help/troubleshooting.md"};function o(r,s,l,h,p,d){return e(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Work through the symptom that matches yours.</p><h2 id="macos-quarantine" tabindex="-1">macOS quarantine (“damaged” or “can’t be opened”) <a class="header-anchor" href="#macos-quarantine" aria-label="Permalink to &quot;macOS quarantine (“damaged” or “can’t be opened”) {#macos-quarantine}&quot;">​</a></h2><p>Browsers tag downloaded apps. Remove the quarantine flag once (adjust the path if the app lives elsewhere):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">APP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/Applications/MindBehindAI.app&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> l</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>Avoid plain <code>xattr -cr</code> on this bundle: it follows symlinks, and bundled Node’s <code>bin/npx</code> / <code>npm</code> / <code>corepack</code> point into <code>lib/node_modules/…</code>. If that subtree is absent for one architecture, <code>xattr</code> reports “No such file” and may fail the whole command. On macOS, <strong><code>xattr -c -s</code></strong> clears extended attributes <strong>on the symlink inode</strong> (<code>-s</code>); do <strong>not</strong> use <code>-h</code> here — with BSD <code>xattr</code>, <strong><code>-h</code> prints help</strong>, not “don’t follow”. You can also allow the app under <strong>System Settings → Privacy &amp; Security</strong>.</p><h2 id="bridge-will-not-start" tabindex="-1">Bridge will not start <a class="header-anchor" href="#bridge-will-not-start" aria-label="Permalink to &quot;Bridge will not start&quot;">​</a></h2><ol><li>On <strong>Home</strong>, read the <strong>Built-in engine</strong> step—if it says unavailable, reinstall or contact support with the exact text.</li><li>Check <strong>Logs</strong> for <code>address already in use</code>—another program is using the HTTP port. Change <strong>Settings → HTTP port</strong> or quit the other program.</li><li>Tap <strong>Apply changes</strong> on Home after large edits under <strong>Connections</strong>.</li></ol><h2 id="tools-missing-in-open-webui" tabindex="-1">Tools missing in Open WebUI <a class="header-anchor" href="#tools-missing-in-open-webui" aria-label="Permalink to &quot;Tools missing in Open WebUI&quot;">​</a></h2><ol><li>Confirm the bridge is <strong>Running</strong> on <strong>Home</strong>.</li><li>Confirm each connection is <strong>enabled</strong> under <strong>My connections</strong>.</li><li>Re-run <strong>Sync enabled connections</strong> on <strong>Integrations → Open WebUI</strong> after editing connections.</li><li>For manual setup, re-copy each <strong>Copy link</strong>—URLs change if you rename a connection.</li></ol><h2 id="oauth-loops-or-expired-login" tabindex="-1">OAuth loops or expired login <a class="header-anchor" href="#oauth-loops-or-expired-login" aria-label="Permalink to &quot;OAuth loops or expired login&quot;">​</a></h2><ol><li>Clear <strong>Settings → OAuth tokens</strong>, then trigger sign-in again from your assistant so the browser opens fresh.</li><li>Make sure pop-up blockers are not blocking the Telekom or Microsoft login window.</li></ol><h2 id="docker-required-preset-fails" tabindex="-1">Docker-required preset fails <a class="header-anchor" href="#docker-required-preset-fails" aria-label="Permalink to &quot;Docker-required preset fails&quot;">​</a></h2><p>Install <strong>Docker Desktop</strong> and wait until it is healthy, then retry the preset. The bridge itself does not run inside Docker.</p><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><p>Collect three things before contacting support:</p><ol><li>A screenshot of <strong>Home</strong> (status strip visible).</li><li>The last ~30 lines from <strong>Logs</strong>.</li><li>Your OS and version (macOS: Apple Silicon or Intel; Windows: edition and 64-bit).</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><strong><a href="./faq.html">FAQ</a></strong></li><li><strong><a href="./../everyday/home.html">Home</a></strong></li></ul>`,19)])])}const c=i(n,[["render",o]]);export{k as __pageData,c as default};
